1	import { describe, it, expect } from "vitest";
2	import { nextGeneration, type Cell } from "./game-of-life.js";
3	
4	// A generation is a set of positions, not a sequence: nextGeneration makes no
5	// promise about ordering. `arrayContaining` alone would pass on extra cells, so
6	// the length check is what makes this an equality rather than a subset test.
7	const expectSameCells = (actual: Cell[], expected: Cell[]): void => {
8	  expect(actual).toEqual(expect.arrayContaining(expected));
9	  expect(actual).toHaveLength(expected.length);
10	};
11	
12	describe("Game of Life - nextGeneration", () => {
13	  it("returns an empty grid for an empty grid — [] → []", () => {
14	    expect(nextGeneration([])).toEqual([]);
15	  });
16	
17	  it("Rule 1 (underpopulation): a single live cell with 0 neighbors dies — [(0,0)] → []", () => {
18	    expect(nextGeneration([[0, 0]])).toEqual([]);
19	  });
20	
21	  it("Rule 1 (underpopulation): two adjacent live cells each with 1 neighbor die — [(0,1), (1,1)] → []", () => {
22	    expect(
23	      nextGeneration([
24	        [0, 1],
25	        [1, 1],
26	      ]),
27	    ).toEqual([]);
28	  });
29	
30	  it("Rule 2 (survival): a live cell with 2 live neighbors lives on — blinker [(0,0), (0,1), (0,2)] keeps (0,1) alive", () => {
31	    expect(
32	      nextGeneration([
33	        [0, 0],
34	        [0, 1],
35	        [0, 2],
36	      ]),
37	    ).toContainEqual([0, 1]);
38	  });
39	
40	  // NOTE: the spec's Rule 2 illustration (### / ... / .#. → .#. / .#. / ...) is
41	  // internally inconsistent: in its own Gen 0 drawing the cell (1,1) is dead and
42	  // has 4 neighbors, not the 3 the prose claims, and the drawn Gen 1 is not what
43	  // Conway's rules produce from the drawn Gen 0. The 3-neighbor survival branch is
44	  // therefore pinned here with an unambiguous configuration — in a 2x2 block every
45	  // live cell has exactly 3 live neighbors and survives.
46	  it("Rule 2 (survival): a live cell with 3 live neighbors lives on — (0,0) in a 2x2 block has 3 neighbors and survives", () => {
47	    expect(
48	      nextGeneration([
49	        [0, 0],
50	        [1, 0],
51	        [0, 1],
52	        [1, 1],
53	      ]),
54	    ).toContainEqual([0, 0]);
55	  });
56	
57	  // NOTE: like the Rule 2 illustration, the spec's Rule 3 drawing
58	  // (### / .#. / ### → #.# / #.# / #.#) is internally inconsistent. In its own
59	  // Gen 0 the center (1,1) has SIX live neighbors, not the 4 the prose claims,
60	  // and the true next generation spills to y=-1 and y=3 rather than being the
61	  // drawn 3x3. The rule itself is sound and is what gets pinned here: (1,1) is
62	  // alive with more than 3 neighbors, so it dies.
63	  it("Rule 3 (overpopulation): a live cell with more than 3 live neighbors dies — center of ### / .#. / ### has 6 and dies", () => {
64	    expect(
65	      nextGeneration([
66	        [0, 0],
67	        [1, 0],
68	        [2, 0],
69	        [1, 1],
70	        [0, 2],
71	        [1, 2],
72	        [2, 2],
73	      ]),
74	    ).not.toContainEqual([1, 1]);
75	  });
76	
77	  it("Rule 4 (reproduction): a dead cell with exactly 3 live neighbors becomes alive — ##. / #.. / ... → ##. / ##. / ...", () => {
78	    const result = nextGeneration([
79	      [0, 0],
80	      [1, 0],
81	      [0, 1],
82	    ]);
83	
84	    expectSameCells(result, [
85	      [0, 0],
86	      [1, 0],
87	      [0, 1],
88	      [1, 1],
89	    ]);
90	  });
91	
92	  it("handles negative coordinates — blinker [(0,0), (0,1), (0,2)] → [(-1,1), (0,1), (1,1)]", () => {
93	    const result = nextGeneration([
94	      [0, 0],
95	      [0, 1],
96	      [0, 2],
97	    ]);
98	
99	    expectSameCells(result, [
100	      [-1, 1],
101	      [0, 1],
102	      [1, 1],
103	    ]);
104	  });
105	
106	  it("block still life stays unchanged — [(0,0), (1,0), (0,1), (1,1)] → same four cells", () => {
107	    const block: Cell[] = [
108	      [0, 0],
109	      [1, 0],
110	      [0, 1],
111	      [1, 1],
112	    ];
113	
114	    const result = nextGeneration(block);
115	
116	    expectSameCells(result, block);
117	  });
118	
119	  it("blinker oscillates back to vertical after two generations — [(-1,1), (0,1), (1,1)] → [(0,0), (0,1), (0,2)]", () => {
120	    const vertical: Cell[] = [
121	      [0, 0],
122	      [0, 1],
123	      [0, 2],
124	    ];
125	
126	    const horizontal = nextGeneration(vertical);
127	    expectSameCells(horizontal, [
128	      [-1, 1],
129	      [0, 1],
130	      [1, 1],
131	    ]);
132	
133	    expectSameCells(nextGeneration(horizontal), vertical);
134	  });
135	
136	  // Rule 4 says EXACTLY 3 neighbors, so the upper bound needs its own test:
137	  // without this, `isBorn` could be `>= 3` and every other test would still pass.
138	  it("Rule 4 (reproduction): a dead cell with more than 3 live neighbors is NOT born — 4 diagonal corners around (1,1) → []", () => {
139	    expect(
140	      nextGeneration([
141	        [0, 0],
142	        [2, 0],
143	        [0, 2],
144	        [2, 2],
145	      ]),
146	    ).toEqual([]);
147	  });
148	
149	  // Rule 3's boundary: the ###/.#./### fixture above has SIX neighbors, which only
150	  // rules out a survival cap of 6+. Exactly 4 is the first count that must die, so
151	  // without this test MAX_NEIGHBORS_TO_SURVIVE could be 4 or 5 and stay green.
152	  it("Rule 3 (overpopulation): a live cell with exactly 4 live neighbors dies — centre of the diagonal cross dies (its four edge cells are born)", () => {
153	    const result = nextGeneration([
154	      [1, 1],
155	      [0, 0],
156	      [2, 0],
157	      [0, 2],
158	      [2, 2],
159	    ]);
160	
161	    expect(result).not.toContainEqual([1, 1]);
162	    expectSameCells(result, [
163	      [0, 1],
164	      [1, 0],
165	      [1, 2],
166	      [2, 1],
167	    ]);
168	  });
169	});
